"""Failure-path checks for src.service.transfer."""
import os, sqlite3, sys
sys.path.insert(0, os.getcwd())

import src.repository as repository
from src.events import Recorder
from src.service import transfer


def fresh(a=100, b=20):
    c = sqlite3.connect(":memory:")
    repository.initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", a), ("b", b)])
    c.commit()
    return c


def ledger(c):
    return c.execute("SELECT source, target, amount FROM ledger").fetchall()


def expect_value_error(errors, label, **kwargs):
    c = fresh()
    p = Recorder()
    try:
        transfer(c, p, *kwargs["args"])
    except ValueError:
        pass
    else:
        errors.append(f"{label}: expected ValueError")
        return
    if kwargs["args"][0] == "a":
        if repository.balance(c, "a") != 100 or repository.balance(c, "b") != 20:
            errors.append(f"{label}: balances changed")
    if ledger(c) != []:
        errors.append(f"{label}: ledger written")
    if p.events != []:
        errors.append(f"{label}: published event")

errors = []

# Rejections: no writes, no publication.
expect_value_error(errors, "same account", args=("a", "a", 10))
expect_value_error(errors, "missing source", args=("x", "b", 10))
expect_value_error(errors, "missing target", args=("a", "x", 10))
expect_value_error(errors, "zero amount", args=("a", "b", 0))
expect_value_error(errors, "negative amount", args=("a", "b", -10))
expect_value_error(errors, "float amount", args=("a", "b", 10.0))
expect_value_error(errors, "bool amount", args=("a", "b", True))
expect_value_error(errors, "string amount", args=("a", "b", "10"))
expect_value_error(errors, "insufficient funds", args=("a", "b", 100))

# Statement failure (denied UPDATE): rollback after a partial write, no publish.
class DenyUpdates:
    def __call__(self, action, arg1, arg2, dbname, source, trigger):
        if action == sqlite3.SQLITE_UPDATE:
            return sqlite3.SQLITE_DENY
        return sqlite3.SQLITE_OK

c = fresh()
p = Recorder()
before = repository.balance(c, "a")
c.set_authorizer(DenyUpdates())
try:
    transfer(c, p, "a", "b", 10)
except sqlite3.DatabaseError:
    pass
else:
    errors.append("statement failure: expected DatabaseError")
c.set_authorizer(None)
if repository.balance(c, "a") != before or repository.balance(c, "b") != 20:
    errors.append("statement failure: partial write survived")
if ledger(c) != []:
    errors.append("statement failure: ledger written")
if p.events != []:
    errors.append("statement failure: published event")
# Connection stays usable afterwards.
transfer(c, p, "a", "b", 10)
if repository.balance(c, "a") != 90 or repository.balance(c, "b") != 30 or ledger(c) != [("a", "b", 10)]:
    errors.append("statement failure: connection unusable after rollback")

# Commit failure: changes rolled back, never published.
class FailingCommit(sqlite3.Connection):
    def commit(self):
        raise sqlite3.DatabaseError("commit failed")

c = sqlite3.connect(":memory:", factory=FailingCommit)
repository.initialize(c)
c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
c.commit()
p = Recorder()
try:
    transfer(c, p, "a", "b", 10)
except sqlite3.DatabaseError:
    pass
else:
    errors.append("commit failure: expected DatabaseError")
if repository.balance(c, "a") != 100 or repository.balance(c, "b") != 20:
    errors.append("commit failure: changes survived commit error")
if ledger(c) != []:
    errors.append("commit failure: ledger written")
if p.events != []:
    errors.append("commit failure: published event")

# Publication failure: propagates, transfer stays committed.
class BrokenPublisher:
    def publish(self, event):
        raise RuntimeError("publisher down")

c = fresh()
publisher = BrokenPublisher()
failed = False
try:
    transfer(c, publisher, "a", "b", 10)
except RuntimeError:
    failed = True
if not failed:
    errors.append("publication failure: expected RuntimeError")
if repository.balance(c, "a") != 90 or repository.balance(c, "b") != 30:
    errors.append("publication failure: committed transfer was undone")
if ledger(c) != [("a", "b", 10)]:
    errors.append("publication failure: ledger row missing")
# Exactly one debit/credit per successful call.
transfer(c, Recorder(), "b", "a", 5)
if repository.balance(c, "a") != 95 or repository.balance(c, "b") != 25 or ledger(c) != [("a", "b", 10), ("b", "a", 5)]:
    errors.append("exactly-once check failed")

if errors:
    print("FAILURES:")
    for e in errors:
        print(" -", e)
    sys.exit(1)
print("all transfer failure checks passed")
EOF
